# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# validate_maturity_at_age ----
## Setup ----
data("data_big")
data_4_model <- FIMSFrame(data_big)
ages <- get_ages(data_4_model)
years <- get_start_year(data_4_model):get_end_year(data_4_model)

maturity_rows <- function(timing = NA_real_, age = ages,
                          observed = stats::plogis(age - 2)) {
  tibble::tibble(
    type = "maturity_at_age",
    fleet = NA_character_,
    age = age,
    length = NA_real_,
    timing = timing,
    observed = observed,
    unit = "proportion",
    uncertainty = NA_character_
  )
}

## IO correctness ----
test_that("validate_maturity_at_age() works with correct inputs", {
  #' @description Test that one row per age with timing = NA is valid.
  expect_true(validate_maturity_at_age(maturity_rows(), ages, years))

  #' @description Test that a timing = NA default plus one year of overrides is valid.
  expect_true(validate_maturity_at_age(
    dplyr::bind_rows(maturity_rows(), maturity_rows(timing = years[2])),
    ages,
    years
  ))

  #' @description Test that rows for every year without a default are valid.
  all_years <- purrr::map(years, \(year) maturity_rows(timing = year)) |>
    dplyr::bind_rows()
  expect_true(validate_maturity_at_age(all_years, ages, years))

  #' @description Test that no maturity_at_age rows is valid.
  expect_true(validate_maturity_at_age(maturity_rows()[0, ], ages, years))
})

## Edge handling ----
test_that("FIMSFrame() keeps the model years when maturity_at_age is added", {
  data_with_maturity <- FIMSFrame(dplyr::bind_rows(
    data_big,
    maturity_rows(),
    maturity_rows(timing = years[2])
  ))

  #' @description Test that maturity_at_age rows do not change the model years or ages.
  expect_equal(get_n_years(data_with_maturity), get_n_years(data_4_model))
  expect_equal(get_ages(data_with_maturity), ages)
})

## Error handling ----
test_that("validate_maturity_at_age() returns correct error messages", {
  #' @description Test that values above 1 return an error.
  expect_error(
    validate_maturity_at_age(maturity_rows(observed = 1.5), ages, years),
    "between 0 and 1"
  )

  #' @description Test that -999 returns an error rather than being treated as missing data.
  expect_error(
    validate_maturity_at_age(maturity_rows(observed = -999), ages, years),
    "between 0 and 1"
  )

  #' @description Test that a unit other than proportion returns an error.
  expect_error(
    validate_maturity_at_age(
      dplyr::mutate(maturity_rows(), unit = "number"),
      ages,
      years
    ),
    "proportion"
  )

  #' @description Test that a fleet-specific row returns an error.
  expect_error(
    validate_maturity_at_age(
      dplyr::mutate(maturity_rows(), fleet = "fleet1"),
      ages,
      years
    ),
    "fleet = NA"
  )

  #' @description Test that the year after the last model year returns an error.
  expect_error(
    validate_maturity_at_age(
      maturity_rows(timing = max(years) + 1),
      ages,
      years
    ),
    "outside the model years"
  )

  #' @description Test that a timing missing an age returns an error.
  expect_error(
    validate_maturity_at_age(
      dplyr::bind_rows(
        maturity_rows(),
        maturity_rows(timing = years[2], age = ages[-1])
      ),
      ages,
      years
    ),
    "one row for each model age"
  )

  #' @description Test that a duplicated age returns an error.
  expect_error(
    validate_maturity_at_age(
      dplyr::bind_rows(maturity_rows(), maturity_rows(age = ages[1])),
      ages,
      years
    ),
    "one row for each model age"
  )

  #' @description Test that missing years without a timing = NA default return an error.
  expect_error(
    validate_maturity_at_age(maturity_rows(timing = years[2]), ages, years),
    "missing year"
  )
})
